board = [obs['c' + str(index)] for index in range(16)]
actions = ['right', 'left', 'up', 'down']
horizontal = 0
vertical = 0
for row in range(4):
    for column in range(3):
        horizontal += abs(board[row * 4 + column] - board[row * 4 + column + 1])
        vertical += abs(board[column * 4 + row] - board[(column + 1) * 4 + row])
best = -1000000
for direction in actions:
    if obs['valid_' + direction]:
        score = 0
        for row in range(4):
            for column in range(3):
                first = row * 4 + column if direction in ('left', 'right') else column * 4 + row
                second = first + 1 if direction in ('left', 'right') else first + 4
                if board[first] == board[second] and board[first] > 0:
                    score += board[first] * 2
        if score > best:
            best = score
            action = direction
